L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_UNIT_DESC_NKM_UNIT_OZ_M_PUPPET"
L17_1 = "近接ユニットのダメージを減らし、継続的な攻撃で自分を強化するアタッカー"
