L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_COLLECTION_UNIT_INTRO_OPR_REPLACER_COMMANDAR"
L37_1 = "リプレイサー・シンジケートの歪んだ思想に同調する者達の中には、将校まで務めた元軍人も多数含まれています。\n彼らは正規軍事組織が改良を重ねてきた体系的な戦略戦術に基づく訓練を組織員に施すことにより、リプレイサー・シンジケートを世界を脅かすほどの組織にまで成長させることに貢献しました。\n彼らの中には戦闘中に投降を選んだ者も一部存在しますが、ほとんどの者は自らが選ばれた人類だという誤った信念を捨てきれずにいます。"
L35_1[1] = L36_1
L35_1[2] = L37_1
