L3_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CC_NORMAL_YG_HARIM_5"
L4_1 = "ホシノ・ウサギ本人が能力を自覚する以前の経歴を調査しました。"
