L20_1 = {}
L21_1 = "SI_DP_MISSION_RESET_INTERVAL_DAILY"
L22_1 = "デイリー"
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_UNIT_SKILL_NAME_REPLACER_CA_KING_HYPER"
L23_1 = "ディメンション・カラミティ"
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_DAYMINE_SOMI"
L24_1 = "デイマイン採掘4チームの情熱的な新入社員であるミウラ・ヒマワリは敵の攻撃能力を低下させる妨害型のサポーターです。\nコールセンターに務めていた頃、今月の笑顔賞を一度たりとも逃したことのない彼女はタスクフォースカンパニー業に転職してからも明るい笑顔を絶やさずにいます。\nまだ仕事が未熟なためチームリーダーに怒られることもしばしばありますが、数々の悪質なクレーマーに鍛えられた元最優秀相談員である彼女は、しばらく落ち込んでもすぐにまた奮い立ち、努力することができます。\nところが、それほどまでに情熱的な彼女の目標は両親にとって誇れる娘になりたいというごくごく平凡なものです。"
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_DAYMINE_HYUNSOO"
L25_1 = "デイマイン採掘4チームのチームリーダーを務めるカウンターのクボタ・ケンジは、同業種の人々とのチームワークで戦うことに長けた切り込み役です。\n本来の彼は剣を振るうことよりも報告書を書くことに慣れている現場の補助職でしたが、不景気と度重なるリストラから生き残るべく、自ら戦闘に貢献するようになりました。\nカウンターになる前、過労によって死の淵をさ迷った経験を持つ彼は、チームメンバーには常日頃から定時の出退勤を推奨しており、残業が発生した際は自らがすべての責任を引き受けてしまいがちです。\nある時は仕事への情熱ゆえに、ある時は昇進のために不断の努力を重ねてきた彼は、今では自分に信頼を寄せている部下達のために現在のポストについています。"
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_PVP_BOT_NAME_4"
L26_1 = "デイマイン採掘4チーム"
