L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_PF_TUTORIAL_TEXUTRE_DUNGEON_CLASS_PROTECT_1_DESC"
L30_1 = "ディフェンダーユニットが前列に位置すると、後列に位置する全ユニットと艦船のダメージが減少します。\n※ただし、ディフェンダーユニットはプロテクト機能を受けません。"
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_DESC_TOOLTIP_55"
L31_1 = "ディフェンダーはレンジャーに対して弱く、スナイパーに対して強いです。"
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_DESC_TOOLTIP_42"
L32_1 = "ディフェンダーの後ろにいるユニットにはプロテクトが適用され、ディフェンダーの数に応じて受けるダメージが減少します。"
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_BD_RYAN"
L33_1 = "ディフェンダーであるライアン・フェリエーは、絶えず位置を変えながら自身に向けられた攻撃を受け流し、鋭い鉄拳で敵を掃討します。\n特殊部隊の出である彼は、プリドウェン機関に来た初日に時代遅れの施設と装備を新調すべきと機関長に対して直言し、執事というあだ名を冠するようになりました。\nそのあだ名に相応しく、職務を怠る機関員達を丁重なやり方で叩き直してくれています。\n侵食体すらも一撃で粉砕する鉄拳により多くの機関員は模範的な勤務態度を身につけましたが、機関長並びにカウンター一同は隙あらば問題事を持ち込んでくるため、彼の鋼のような魂も大いに試されています。"
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_DP_STAT_SHORT_DESC_NST_ROLE_TYPE_DEFFENDER_DAMAGE_REDUCE_RATE"
L34_1 = "ディフェンダークラスの敵から受けるダメージを減少させます。ダメージ減少の合計は80％まで適用されます。"
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_UNIT_DESC_M_ADMIN_MACHINEGUN"
L35_1 = "ディフェンダークラスに強く攻撃を維持するほど強くなる"
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_DP_STAT_SHORT_DESC_NST_DEFENDER_PROTECT_RATE"
L36_1 = "ディフェンダークラスがダメージ範囲内にいると、範囲内のディフェンダークラスを除いたユニット全員および艦船にダメージ減少が適用されます。"
L34_1[1] = L35_1
