L28_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_4"
L29_1 = "タスクプラネット3月7日付の特集記事で抜粋\n結局、デイマインはせっかく手に入れた空間座標でもエタニウムを得られなかった。\nこの事例は、現在急成長しているタスクフォースカンパニー業界に示唆する点が多い。"
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_2"
L30_1 = "タスクプラネット3月7日付の特集記事で抜粋\nタスクフォースカンパニーは、優秀な人材と彼らを支える装備が必要だ。\nしかし、デイマインの首脳部は投資に消極的で効率性の追求という名目の下、随所で予算を削減した。"
L28_1[1] = L29_1
