L5_1 = "SI_PF_TUTORIAL_TEXUTRE_EQUIP_TUNING_1_DESC"
L6_1 = "<COLOR=#FFBC00>チューニング</COLOR>を通じて装備の付加オプションの精密度を増加させたり、オプションを変更したりできます。\nチューニングにはクレジットと<COLOR=#FFBC00>チューニングバイナリー</COLOR>が必要です。\n\n装備のティア、レアリティが高いほど費用が増加します。"
L4_1[1] = L5_1
L4_1[2] = L6_1
