L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_1_1_HM"
L48_1 = "銃声で朝が始まり、砲声で眠る。"
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_1_2"
L49_1 = "グロニア反乱軍の始まりは暴力的な反政府団体だというのが定説だ。彼らは管理失敗直後の混乱の中で暴力事件を起こし、侵食災害による政府首脳の不在という悪材料に乗じて勢力を固めた。"
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_1_INTERLUDE_1"
L50_1 = "グロニア保安局とは、国内外の情報収集を担当しており、捜査権までも保持している情報機関である。かつて保安局はその力を利用し、自国に全能の存在として君臨していた。\n内戦勃発の直後、大々的な政府改編によりブレーキをかけられたものの、その悪名は国民の脳裏に強烈に残っている。"
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_2_1"
L51_1 = "長い内戦で消耗した政府軍の軍事力は、反乱軍の散発的な攻勢を抑えるに止まっている。これに対し建国記念日を準備している政府は海外で傭兵を雇用しはじめた。ただ、労働強度と劣悪な条件のため優秀な戦力はいつも足りない状態だ。"
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
