L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_2_INTERLUDE_2"
L15_1 = "夢を見てるんだと思った。それほど非現実的なことだったから。\n悪夢が現実よりましだなんて……予想できなかったけど。"
L13_1[1] = L14_1
L13_1[2] = L15_1
