L19_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_KINGDOM_2_INTERLUDE_4"
L20_1 = "みんなそれぞれ傷を抱えて生きていく。\nそれは、最初は自分を挫折させようとするが、結局は目的を持って生きていく原動力になる。"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_KINGDOM_2_2"
L21_1 = "侵食を経験する前には人が住んでいた地だった。\nだが、聖遺物を失った国の国境は徐々に後退しつづけ、結局は今の三度目の国境であるシャーウッド外郭までたどり着いた。"
L19_1[1] = L20_1
