L21_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_KINGDOM_2_3"
L22_1 = "シャドウは生前自分が願っていたことに執着する。\n亡霊と異なるところは、悪夢の中でではなく現実で出くわすというところだ。"
L20_1[1] = L21_1
L20_1[2] = L22_1
