L32_1 = {}
L33_1 = "SI_UNIT_DESC_NKM_UNIT_ESPR_C_SWORD"
L34_1 = "HPが少なくなった敵にさらに大きなダメージを与える遠距離アタッカー"
L32_1[1] = L33_1
L32_1[2] = L34_1
