L3_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_BG_CHARADE2"
L4_1 = "開けた展望と多様な商業施設。シャレードの1等市民にとっても、この場所は羨望の的だ。\nロビーの背景に使用できます。"
L2_1[1] = L3_1
