L14_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_RAS_MA_DINO@AB_UI_UNIT_VOICE_NKM_UNIT_RAS_MA_DINO_LOBBY_CAPTAIN"
L15_1 = "はい、やるよ。"
