L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB001_1_INTERLUDE_1"
L6_1 = "イノの演奏は心に響きます。あまりにも激しく、荒々しく響くのは問題ですが。"
L4_1[1] = L5_1
L4_1[2] = L6_1
