L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE13"
L11_1 = "亡くなった人への憎悪、後悔、虚脱感。色んな感情がこみあげてきたけど、その中にはちょっとした安心感もあった。"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE14"
L12_1 = "私は、あの子がもう苦しまないでほしかった。でも、どうしても決められないままでいた。"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE15"
L13_1 = "あの子が苦しんでいる間にも、私は治療薬を作るために研究に没頭した。時間がいくら残っていようとも、あの子のそばも守るべきだったのに……バカバカしくも、怖かったようだ。"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE16"
L14_1 = "あの子が消えたのは……本来ならあの子が一番幸せでないといけない日だった。"
