L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE17"
L15_1 = "あの時、私がどんな誕生日プレゼントを用意してたのか……もう上手く思い出せない。侵食症候群のせいだろうか？　もしかしたら、あの日のことを思い出したくなかったのかもしれない。"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE18"
L16_1 = "そう……あの子が一番好きだったのは子守歌だった。そばで歌ってあげると、いつも笑顔で眠りについていたから。"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
