L26_1 = {}
L27_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_YAKSHA_3_3"
L28_1 = "それが、私があなたのために背負うことができる唯一の責任。\nそれが、あなたを救うため私に残された唯一の選択。\nあなたの死をシャドウによって塗りつぶさせない、私の願いであり、決意よ！"
L26_1[1] = L27_1
L26_1[2] = L28_1
