L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_AVENGER_PROLOGUE"
L37_1 = "凍土で生き残る方法は人それぞれだった。切り株のドルイドとその導き手は知識を信仰にした。"
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_AVENGER_INTERLUDE1"
L38_1 = "反逆者に殺されたアバロンの昔の王が近い将来、凍土で生まれ変わり、切り株を導くであろう。"
L36_1[1] = L37_1
L36_1[2] = L38_1
