L38_1 = {}
L39_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_AVENGER_1_2"
L40_1 = "魔物はもっとも大きな災害だ。疫病をもたらし、人類の存続を脅かす。しかし我々はそれがどこから来たのか知らない。"
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_AVENGER_INTERLUDE2"
L41_1 = "アバロンは予言を信じていた。妖精たちが伝えてくれる黄金の木のささやきは外れたことがなかった。"
L39_1[1] = L40_1
L39_1[2] = L41_1
