L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_VARUNA_PROLOGUE"
L24_1 = "ロータスは定期的に短い砂嵐が発生する。\n誰も確かな理由をわかっていないが、時に身元を把握できない様々な人の声が聞こえてくるという。"
L22_1[1] = L23_1
