L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_VARUNA_1_1"
L26_1 = "ロータスの治安は不安定で、様々な犯罪組織の隠れ家となった。\nその中でもっとも有名な犯罪組織はスカベンジャーと言えるだろう。\n彼らは大胆にもロータスの外郭に補給基地を建設し、必要な物資を調達したりする。"
L24_1[1] = L25_1
L24_1[2] = L26_1
