L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_VARUNA_2_3"
L42_1 = "おお、世に珍しい老鯨よ。\n君の家は激しい嵐吹く海の真ん中。\n力こそが正義であるところに住む強い巨神よ、\n君は果てしなき海の王である。"
L40_1[1] = L41_1
L40_1[2] = L42_1
