L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_MOONLIGHT_INTERLUDE19"
L30_1 = "愚かな宿願から解放された私たちは、何のために生きていくべきなのだろう。"
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_MOONLIGHT_INTERLUDE20"
L31_1 = "手伝ってくれそうに言っておいて、いつもダメだって！\nじゃあ、何も言わないでほしいよ！\n人を期待させといてなんだよ、これ。"
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
