L15_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT_LOBBY_TOUCH_NORMAL_1"
L16_1 = "バーネット……まだその名を覚えているのか、古い声よ。だがその名の男はもう死んだ。今の俺は湖の騎士。知識の湖を守る存在であり、我が母ガアグシェブラの使徒だ。"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT_LOBBY_TOUCH_NORMAL_2"
L17_1 = "ヤルダバオトの子供はお母さんの顕現のために集結した教団だ。存在意義を失った学会を排除し、バラバラになっている知識の湖を一つにまとめたその時、俺たちの崇高な役目は果たされる。"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT_LOBBY_TOUCH_NORMAL_3"
L18_1 = "湖の加護たる俺は、今のこの生を授けてくださった我が母、ガアグシェブラの本質のみを仕える。その大いなる意志を阻むのなら……機関も、学会も、そして古い声……貴様も俺の敵だ。"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT_LOBBY_TOUCH_NORMAL_4"
L19_1 = "俺の記憶の片鱗に残るペンドラゴン家の令嬢は、もう少し小さく華奢な少女だったはずだが……こっちの世界のペンドラゴンは、いつの間にか怖い物知らずのお嬢さんに育ってしまったな。ふっ、感慨深いものだ。"
L17_1[1] = L18_1
L17_1[2] = L19_1
