L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_INTERLUDE2"
L43_1 = "囚人を船に乗せるための条件はかなり厳しいものだった。\nその1、フロントベイで一定期間の間賞金を受け取ったことのある者であること。\nその2、正式に認可されたタスクフォースであること。\nその3、海賊であること。"
L41_1[1] = L42_1
L41_1[2] = L43_1
