L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_1_1"
L44_1 = "赤い靴を履いていればどこにでも行ける。\n靴を履いた足が熱くなって踊ることを止められなくなっても、必ず君の居るところまで駆けていくよ。"
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_OMEN_5_1_2"
L45_1 = "犬たちの宴会"
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_1_2"
L46_1 = "猟犬は飼い主のために獲物を追いかける。\n闘犬は飼い主のために犬と戦う。\nしかし狂犬が誰のために牙を剥くか、その理由を知る術はない。"
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_INTERLUDE2"
L47_1 = "彼女は知っている。\n人の目に見えないものが見えるということは優越感をもたらすものではないことを。\nむしろ呪いに近いということを。"
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_INTERLUDE3"
L48_1 = "彼女の表向きの身分はジョニー＆メロニーの代表兼一流弁護士。\n政財界のあらゆる事件を担当し、影響力を高めてきた彼女だが、ラムダ・スパタリーの本当の姿を知る人は多くない。"
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
